const tmp=await fs.mkdtemp(path.join(os.tmpdir(),'easygas-workflows-'));const storage=new Map();globalThis.localStorage={getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)};globalThis.sessionStorage={setItem(){}};globalThis.location={href:'https://review.invalid/',origin:'https://review.invalid',pathname:'/',search:''};globalThis.window=Object.assign(new EventTarget(),{scrollTo(){}});globalThis.document={addEventListener(){}};globalThis.history={pushState(){},replaceState(){}};
