const call=(action,data)=>{const r=m.request(action,data);assert.ok(!r?.__status,action+': '+r?.error);return r;};const as=(role,action,data)=>{m.state.role=role;return call(action,data)};const reject=(action,data)=>{const r=m.request(action,data);assert.ok(r?.__status>=400,action+' should reject');return r};const D=()=>{call('workflow.snapshot');return m.state.domain};const snapshot=()=>call('workflow.snapshot');const product=()=>D().products.find(p=>p.id==='cylinder-empty-6');const addr={street:'12 Workflow Avenue',zone:'Victoria Island',locationId:'victoria-island',phone:'08000000000'};
function order(method='wallet',kg=6){return as('customer','checkout',{gasLines:[{kg,capacityKg:6}],address:addr,date:'2026-11-21',window:'09:00–12:00',paymentMethod:method,idempotencyKey:crypto.randomUUID()});}
function proposal(module,action,data,maker='finance',reviewer='owner',execute=true){const row=as(maker,'business.propose',{module,action,data});as(reviewer,'business.approve',{id:row.id,revision:1});if(execute)as(reviewer,'business.execute',{id:row.id,revision:1});return D().proposals.find(r=>r.id===row.id);}
function qualify(role){const ref=m.user(role).id,r=as('manager','qualification.request',{reference:ref,evidence:'synthetic QA only'});as('owner','qualification.verify',{id:r.id,synthetic:true});return D().qualifications.find(q=>q.id===r.id);}
function assignedOrder(){const o=order('cash_on_delivery');as('manager','order.transition',{id:o.id,status:'accepted'});as('finance','gas.inspect',{orderId:o.id,evidence:'synthetic cylinder inspection'});as('manager','order.coverage',{orderId:o.id,evidence:'synthetic address boundary'});as('manager','order.transition',{id:o.id,status:'preparing'});as('driver','driver.availability',{available:true});as('manager','dispatch.assign',{orderId:o.id,driverId:m.user('driver').id});return m.state.orders.find(x=>x.id===o.id);}
function delivery(stop='complete'){const o=assignedOrder(),trip=as('driver','trip.start',{odometer:100});qualify('driver');const load=as('finance','bulk.load.issue',{tripId:trip.id,grams:6000,meterId:D().meters[0].id});as('driver','bulk.load.acknowledge',{loadId:load.id});as('driver','dispatch.respond',{orderId:o.id,decision:'accepted',reason:'Synthetic assignment checked'});as('driver','delivery.pickup',{orderId:o.id,syntheticInspection:true});if(stop==='pickup')return{o,trip,load};as('driver','delivery.arrived',{orderId:o.id});if(stop==='arrived')return{o,trip,load};as('driver','bulk.dispense',{orderId:o.id,loadId:load.id,grams:6000});if(stop==='dispensed')return{o,trip,load};as('driver','delivery.complete',{orderId:o.id,customerCode:'123456',syntheticProof:true,description:'synthetic handover only'});if(stop==='complete')return{o,trip,load};as('driver','bulk.return.declare',{loadId:load.id,grams:0});as('finance','bulk.return.verify',{id:load.id,evidence:'synthetic independent zero return'});as('driver','trip.end',{tripId:trip.id,odometer:110});as('finance','order.cash.verify',{orderId:o.id,evidence:'synthetic cash count'});return{o,trip,load};}
function booking(stop='settled'){let b=as('customer','booking.create',{serviceId:'cooker-installation',address:addr,preferredDate:'2026-11-21',idempotencyKey:crypto.randomUUID()});if(stop==='requested')return m.state.bookings.find(x=>x.id===b.id);as('manager','booking.assign',{bookingId:b.id,technicianId:m.user('technician').id,startsAt:'2026-11-21T09:00:00Z'});as('technician','booking.assignment.respond',{bookingId:b.id,decision:'accepted'});if(stop==='assigned')return m.state.bookings.find(x=>x.id===b.id);as('technician','booking.assessment.save',{bookingId:b.id,scope:'Inspect and install',evidence:'synthetic assessment'});if(stop==='assessed')return m.state.bookings.find(x=>x.id===b.id);as('manager','booking.quote',{bookingId:b.id,scope:'Install after assessment',labourKobo:100000,materialsKobo:50000});as('manager','booking.quote.request_review',{bookingId:b.id});as('owner','booking.quote.approve',{bookingId:b.id});if(stop==='quoted')return m.state.bookings.find(x=>x.id===b.id);as('customer','booking.quote.accept',{bookingId:b.id,version:1,consent:true});if(stop==='authorised')return m.state.bookings.find(x=>x.id===b.id);qualify('technician');as('technician','booking.work.start',{bookingId:b.id});if(stop==='started')return m.state.bookings.find(x=>x.id===b.id);as('finance','service.material.issue',{bookingId:b.id,productId:product().id,quantity:1});as('technician','service.material.usage',{bookingId:b.id,materialId:m.state.bookings.find(x=>x.id===b.id).materials[0].id,quantity:1});as('technician','booking.report',{bookingId:b.id,summary:'Installed to the reviewed local scope',syntheticProof:true});if(stop==='reported')return m.state.bookings.find(x=>x.id===b.id);as('customer','booking.acknowledge',{bookingId:b.id});as('customer','booking.wallet.pay',{bookingId:b.id});as('finance','booking.settle',{bookingId:b.id});return m.state.bookings.find(x=>x.id===b.id);}
function campaign(){as('customer','preferences.save',{marketing:true,refillReminders:true,serviceReminders:true});proposal('campaigns','New campaign',{name:'Local refill reminder',audience:'Opted-in customers',message:'Review your local refill plan'},'owner','owner');return D().campaigns[0];}
